            if len(set(clause)) == 2:
                clauses.append(clause)
        return clauses

    def resolution_width(clauses):
        queue = set()
        unit_clauses = {i: [] for i in range(1, n + 1)}

        for clause in clauses:
            if len(clause) == 1:
                unit_clauses[abs(clause[0])].append(clause)
                queue.add(clause)

